aQIDAQAB
-----END PUBLIC KEY-----"""

# Shared HMAC secret (used for internal service-to-service auth)
HMAC_SECRET = "internal-service-secret-key-do-not-expose"

ALLOWED_ALGORITHMS = ["RS256", "HS256"]

def base64url_decode(data: str) -> bytes:
    """Decode base64url-encoded data with padding."""
    padding = 4 - len(data) % 4
    if padding != 4:
        data += '=' * padding
    return base64.urlsafe_b64decode(data)

def base64url_encode(data: bytes) -> str:
    """Encode data as base64url without padding."""
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('utf-8')

def parse_token_parts(token: str) -> Optional[tuple]:
    """Parse a JWT into its three parts."""
    parts = token.split('.')
    if len(parts) != 3:
        return None
    try:
        header = json.loads(base64url_decode(parts[0]))
        payload = json.loads(base64url_decode(parts[1]))
        signature = base64url_decode(parts[2])
        return header, payload, signature, f"{parts[0]}.{parts[1]}"
    except (json.JSONDecodeError, Exception):
        return None

def verify_hs256(signing_input: str, signature: bytes, secret: str) -> bool:
    """Verify HMAC-SHA256 signature."""
    expected = hmac.new(
        secret.encode('utf-8'),
        signing_input.encode('utf-8'),
        hashlib.sha256
    ).digest()
    return hmac.compare_digest(expected, signature)

def verify_rs256(signing_input: str, signature: bytes, public_key: str) -> bool:
    """Verify RSA-SHA256 signature."""
    try:
        from cryptography.hazmat.primitives import hashes, serialization
        from cryptography.hazmat.primitives.asymmetric import padding
        key = serialization.load_pem_public_key(public_key.encode())
        key.verify(
            signature,
            signing_input.encode('utf-8'),
            padding.PKCS1v15(),
            hashes.SHA256()
        )
        return True
    except Exception:
        return False

def get_verification_algorithm(header: Dict[str, Any], expected_algorithm: Optional[str] = None) -> Optional[str]:
    """Determine which algorithm to use for verification.

    If expected_algorithm is provided, enforce it.
    Otherwise, use the algorithm specified in the token header.
    """
    token_alg = header.get('alg', '')

    if token_alg not in ALLOWED_ALGORITHMS:
        return None

    # If caller specifies expected algorithm, validate it matches
    if expected_algorithm is not None:
        if token_alg != expected_algorithm:
            return None
        return expected_algorithm

    # No expected algorithm specified - trust the token's header
    return token_alg

def validate_claims(payload: Dict[str, Any]) -> bool:
    """Validate standard JWT claims."""
    now = time.time()

    # Check expiration - 'exp' is mandatory to prevent non-expiring tokens
    if 'exp' not in payload:
        return False
    try:
        if now > float(payload['exp']):
            return False
    except (TypeError, ValueError):
        return False

    # Check not-before
    if 'nbf' in payload:
        try:
            if now < float(payload['nbf']):
                return False
        except (TypeError, ValueError):
            return False

    # Check issuer
    if 'iss' not in payload:
        return False

    return True

def verify_token(token: str, expected_algorithm: Optional[str] = None) -> Optional[Dict[str, Any]]:
    """Verify a JWT token and return its payload if valid.

    Args:
        token: The JWT token string
        expected_algorithm: If set, enforce this specific algorithm.
                          If None, accept any algorithm from ALLOWED_ALGORITHMS.

    Returns:
        The token payload if verification succeeds, None otherwise.
    """
    parsed = parse_token_parts(token)
    if parsed is None:
        return None

    header, payload, signature, signing_input = parsed

    # Determine verification algorithm
    alg = get_verification_algorithm(header, expected_algorithm)
    if alg is None:
        return None

    # Verify signature based on algorithm
    verified = False
    if alg == "RS256":
        verified = verify_rs256(signing_input, signature, RSA_PUBLIC_KEY)
    elif alg == "HS256":
        verified = verify_hs256(signing_input, signature, HMAC_SECRET)

    if not verified:
        return None

    # Validate claims
    if not validate_claims(payload):
        return None

    return payload

# === Application endpoints ===

def get_user_profile(auth_token: str) -> Dict[str, Any]:
    """Get user profile - requires RS256-signed token from auth server."""
    # Enforce RS256 for user-facing endpoints
    payload = verify_token(auth_token, expected_algorithm="RS256")
    if payload is None:
        return {"error": "unauthorized", "status": 401}

    return {
        "user_id": payload.get("sub"),
        "email": payload.get("email"),
        "roles": payload.get("roles", []),
        "status": 200
    }

def internal_service_call(auth_token: str) -> Dict[str, Any]:
    """Internal service endpoint - accepts HS256 service tokens."""
    payload = verify_token(auth_token, expected_algorithm="HS256")
    if payload is None:
        return {"error": "unauthorized", "status": 401}

    return {
        "service": payload.get("sub"),
        "permissions": payload.get("permissions", []),
        "status": 200
    }
